1) Fix: Service Worker registration error (same-origin guard)

Cause: navigator.serviceWorker.register('sw.js') tries to register sw.js from the current origin. In Studio preview the page is served from a different origin than where sw.js is being loaded (or Studio rewrites URLs), so registration fails with an origin mismatch.

Fix: Register the service worker only when all of these are true:

navigator.serviceWorker exists

Page is loaded over https or localhost

sw.js is available on the same origin (i.e., use a relative path like ./sw.js)

OR explicitly skip SW registration in ephemeral preview environments (Google AI Studio) — detect with window.location.hostname or window.origin heuristics.

Paste this guarded code where you currently register the SW:

// Safe service worker registration (guarded for Studio preview / cross-origin environments)
(function registerServiceWorkerSafely(){
  if (!('serviceWorker' in navigator)) {
    console.debug('ServiceWorker not supported in this browser.');
    return;
  }

  // Only register on secure origins or localhost
  const isLocalhost = location.hostname === 'localhost' || location.hostname === '127.0.0.1';
  const isSecure = location.protocol === 'https:';
  if (!isSecure && !isLocalhost) {
    console.debug('Skipping SW registration: not HTTPS or localhost.');
    return;
  }

  // Ensure sw.js is same-origin and reachable via a simple fetch probe
  const swUrl = './sw.js'; // use relative path to ensure same-origin
  fetch(swUrl, { method: 'HEAD', cache: 'no-store' })
    .then(resp => {
      // success status indicates we can register the SW from same origin
      if (!resp.ok) throw new Error('sw.js not reachable (status ' + resp.status + ')');
      return navigator.serviceWorker.register(swUrl);
    })
    .then(reg => {
      console.debug('ServiceWorker registered:', reg.scope);
    })
    .catch(err => {
      // Common in Studio preview — avoid spamming user with errors
      console.warn('SW registration skipped or failed:', err && err.message ? err.message : err);
    });
})();

// src/utils/exporter.ts
// Robust PDF exporter using html2pdf.js with preloading of images & fonts.
// Usage: import { exportProjectToPDF } from './utils/exporter';
// then call exportProjectToPDF(project, { fileName: 'my-case-study.pdf' });

type ExportOptions = {
  fileName?: string;
  timeoutMs?: number; // how long to wait for images/fonts
  marginMm?: number;
};

const DEFAULTS: Required<ExportOptions> = {
  fileName: 'case-study.pdf',
  timeoutMs: 8000,
  marginMm: 10,
};

function loadScriptOnce(src: string): Promise<void> {
  return new Promise((resolve, reject) => {
    if ((window as any).html2pdf) return resolve();
    // avoid duplicate insertion
    if (document.querySelector(`script[data-src="${src}"]`)) {
      // wait until window.html2pdf exists
      const check = setInterval(() => {
        if ((window as any).html2pdf) {
          clearInterval(check);
          resolve();
        }
      }, 200);
      setTimeout(() => {
        clearInterval(check);
        if ((window as any).html2pdf) resolve();
        else reject(new Error('html2pdf load timeout'));
      }, 8000);
      return;
    }
    const s = document.createElement('script');
    s.src = src;
    s.async = true;
    s.defer = true;
    s.setAttribute('data-src', src);
    s.onload = () => {
      // some CDNs export html2pdf on window
      if ((window as any).html2pdf) return resolve();
      // small delay to allow lib to attach
      setTimeout(() => {
        if ((window as any).html2pdf) resolve();
        else reject(new Error('html2pdf loaded but not available on window'));
      }, 200);
    };
    s.onerror = (e) => reject(new Error('Failed to load script ' + src));
    document.head.appendChild(s);
  });
}

async function ensureHtml2PdfLoaded(): Promise<void> {
  // html2pdf.bundle includes html2canvas + jspdf
  const cdn = 'https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.9.2/html2pdf.bundle.min.js';
  return loadScriptOnce(cdn);
}

function createSpinnerModal(): { el: HTMLElement; show: () => void; hide: () => void } {
  const el = document.createElement('div');
  el.setAttribute('role', 'status');
  el.style.position = 'fixed';
  el.style.left = '0';
  el.style.top = '0';
  el.style.right = '0';
  el.style.bottom = '0';
  el.style.display = 'flex';
  el.style.alignItems = 'center';
  el.style.justifyContent = 'center';
  el.style.background = 'rgba(0,0,0,0.5)';
  el.style.zIndex = '999999';
  el.style.visibility = 'hidden';
  el.innerHTML = `
    <div style="background:#fff;padding:18px 22px;border-radius:10px;display:flex;gap:12px;align-items:center;max-width:320px">
      <div class="uxmate-spinner" style="width:36px;height:36px;border-radius:50%;border:4px solid #e6eef8;border-top-color: #60a5fa; animation: uxmate-spin 1s linear infinite"></div>
      <div style="font-family: Inter, Arial, sans-serif; color:#061022; font-size:14px; font-weight:600">Preparing PDF — please wait…</div>
    </div>
    <style>
      @keyframes uxmate-spin { to { transform: rotate(360deg); } }
    </style>
  `;
  document.body.appendChild(el);
  return {
    el,
    show() { el.style.visibility = 'visible'; },
    hide() { el.style.visibility = 'hidden'; setTimeout(()=> el.remove(), 300); },
  };
}

function waitForImagesAndFonts(root: HTMLElement, timeoutMs: number): Promise<void> {
  return new Promise((resolve, reject) => {
    const imgs = Array.from(root.querySelectorAll('img')) as HTMLImageElement[];
    let pending = imgs.length;

    // If no images, still wait a tiny moment to ensure layout settle
    if (pending === 0) {
      // Wait for fonts (if any) using document.fonts.ready
      Promise.resolve().then(() => {
        if ((document as any).fonts && (document as any).fonts.ready) {
          (document as any).fonts.ready.then(() => setTimeout(resolve, 120));
        } else {
          setTimeout(resolve, 120);
        }
      });
      return;
    }

    const onDone = () => {
      // also wait for fonts a tiny bit to avoid invisible text
      if ((document as any).fonts && (document as any).fonts.ready) {
        (document as any).fonts.ready.then(() => resolve()).catch(()=>resolve());
      } else {
        resolve();
      }
    };

    const timer = setTimeout(() => {
      // if images still pending, resolve anyway but mark as timeout
      console.warn('exporter: image load timeout after', timeoutMs, 'ms');
      onDone();
    }, timeoutMs);

    if (imgs.length === 0) { clearTimeout(timer); onDone(); return; }

    imgs.forEach((img) => {
      // If image already loaded and has naturalWidth, treat as done
      if (img.complete && img.naturalWidth && img.naturalWidth > 0) {
        pending--;
        if (pending === 0) {
          clearTimeout(timer);
          onDone();
        }
        return;
      }
      // Try to load (set crossOrigin to anonymous where possible)
      const handleLoad = () => {
        img.removeEventListener('load', handleLoad);
        img.removeEventListener('error', handleError);
        pending--;
        if (pending === 0) {
          clearTimeout(timer);
          onDone();
        }
      };
      const handleError = () => {
        img.removeEventListener('load', handleLoad);
        img.removeEventListener('error', handleError);
        console.warn('exporter: image failed to load for PDF export', img.src);
        pending--;
        if (pending === 0) {
          clearTimeout(timer);
          onDone();
        }
      };
      img.addEventListener('load', handleLoad);
      img.addEventListener('error', handleError);
      // if image has no src or is dataURL, it may still trigger complete later; leave listeners
    });
  });
}

/**
 * Clone node for PDF rendering:
 * - clones the element
 * - applies an off-screen container that remains visible to layout engines
 */
function createOffscreenClone(node: HTMLElement): HTMLElement {
  const clone = node.cloneNode(true) as HTMLElement;

  // create wrapper that is off-screen but has layout
  const wrapper = document.createElement('div');
  wrapper.style.position = 'fixed';
  wrapper.style.left = '-9999px';
  wrapper.style.top = '0';
  wrapper.style.width = node.getBoundingClientRect().width + 'px';
  wrapper.style.padding = '20px';
  wrapper.style.background = '#ffffff';
  wrapper.style.color = '#111';
  wrapper.style.zIndex = '999998';
  wrapper.appendChild(clone);

  // copy computed styles for critical elements? (we rely on existing CSS being global)
  document.body.appendChild(wrapper);
  return wrapper;
}

/**
 * Main export function
 * @param rootNode HTMLElement - the case-study DOM node (not the whole app)
 * @param options ExportOptions
 */
export async function exportNodeToPDF(rootNode: HTMLElement, options?: ExportOptions): Promise<void> {
  const opts = { ...DEFAULTS, ...(options || {}) };
  if (!rootNode) throw new Error('exportNodeToPDF: rootNode is required');

  // load library
  await ensureHtml2PdfLoaded();

  const spinner = createSpinnerModal();
  spinner.show();

  // Clone node into off-screen visible wrapper
  const wrapper = createOffscreenClone(rootNode);
  try {
    // Wait for images & fonts inside the clone
    await waitForImagesAndFonts(wrapper, opts.timeoutMs);

    // prepare html2pdf options
    const html2pdf = (window as any).html2pdf;
    if (!html2pdf) throw new Error('html2pdf is not available on window');

    const pdfOptions = {
      margin: opts.marginMm,
      filename: opts.fileName,
      image: { type: 'jpeg', quality: 0.92 },
      html2canvas: { useCORS: true, scale: 2, allowTaint: false },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
    };

    // Perform export
    await new Promise<void>((resolve, reject) => {
      try {
        // html2pdf().from(wrapper).set(pdfOptions).save();
        const worker = html2pdf().from(wrapper).set(pdfOptions).save();
        // html2pdf returns a Promise-like for save
        if (worker && typeof worker.then === 'function') {
          worker.then(() => resolve()).catch((err: any) => reject(err));
        } else {
          // fallback: resolve after small delay
          setTimeout(() => resolve(), 1200);
        }
      } catch (err) {
        reject(err);
      }
    });
  } catch (err) {
    console.error('exportNodeToPDF error:', err);
    // fallback: offer HTML export by creating a downloadable HTML file
    const html = wrapper.innerHTML || rootNode.innerHTML;
    const blob = new Blob([`<!doctype html><html><head><meta charset="utf-8"></head><body>${html}</body></html>`], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = (opts.fileName || 'case-study') + '.html';
    a.click();
    URL.revokeObjectURL(url);
    alert('PDF export failed. An HTML export has been downloaded as fallback.');
  } finally {
    spinner.hide();
    // cleanup wrapper
    if (wrapper && wrapper.parentNode) wrapper.parentNode.removeChild(wrapper);
  }
}

/**
 * Convenience: export project object (assumes you have a function that renders the project into DOM)
 * - You must pass the actual DOM node that represents the case study.
 */
export async function exportProjectToPDF(projectId: string, rootSelectorOrNode: string | HTMLElement, options?: ExportOptions) {
  let rootNode: HTMLElement | null = null;
  if (typeof rootSelectorOrNode === 'string') {
    rootNode = document.querySelector(rootSelectorOrNode) as HTMLElement;
  } else {
    rootNode = rootSelectorOrNode as HTMLElement;
  }
  if (!rootNode) throw new Error('exportProjectToPDF: could not find root node: ' + rootSelectorOrNode);
  await exportNodeToPDF(rootNode, options);
}


