// utils/export-print-inline.js
// Client-side robust print exporter — converts images to dataURLs, opens new window and triggers print.

async function imageToDataURL(img) {
  return new Promise((resolve) => {
    try {
      const canvas = document.createElement('canvas');
      const w = img.naturalWidth || img.width || 1;
      const h = img.naturalHeight || img.height || 1;
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext('2d');
      // try to draw, may throw if cross-origin without CORS
      try {
        ctx.drawImage(img, 0, 0, w, h);
        const dataURL = canvas.toDataURL('image/png', 0.92);
        resolve(dataURL);
      } catch (err) {
        // fallback: fetch direct (if same-origin or CORS allows), else ignore image
        if (img.src && img.src.startsWith('data:')) return resolve(img.src);
        fetch(img.src, {mode: 'cors'}).then(resp => resp.blob()).then(blob => {
          const r = new FileReader();
          r.onload = () => resolve(r.result);
          r.readAsDataURL(blob);
        }).catch(()=> {
          console.warn('Could not inline image:', img.src);
          resolve(img.src); // leave as-is (may be blocked)
        });
      }
    } catch (e) {
      console.warn('imageToDataURL error', e, img.src);
      resolve(img.src || '');
    }
  });
}

async function inlineAllImages(root) {
  const imgs = Array.from(root.querySelectorAll('img'));
  for (const img of imgs) {
    try {
      if (!img.src) continue;
      if (img.src.startsWith('data:')) continue;
      const dataUrl = await imageToDataURL(img);
      if (dataUrl) img.setAttribute('src', dataUrl);
      // remove crossorigin to avoid future issues
      img.removeAttribute('crossorigin');
    } catch (e) {
      console.warn('Failed to inline image', e, img.src);
    }
  }
}

// Helper to get stylesheet rules as text to include in export
function collectStylesheetText() {
  let cssText = '';
  for (const sheet of document.styleSheets) {
    try {
      if (!sheet.cssRules) continue;
      for (const rule of sheet.cssRules) {
        cssText += rule.cssText + '\n';
      }
    } catch (e) {
      // ignore CORS-restricted stylesheets
    }
  }
  // also add basic resets if desired
  cssText += `
    img { max-width: 100%; height: auto; }
    body { background: #fff; color: #111; }
  `;
  return cssText;
}

/**
 * Export DOM node to printable window and call print.
 * @param {HTMLElement|string} rootOrSelector - DOM element or selector
 * @param {Object} opts - {fileName, waitMs}
 */
async function exportCaseStudyWithInlinePrint(rootOrSelector, opts = {}) {
  const fileName = opts.fileName || 'case-study.pdf';
  const waitMs = typeof opts.waitMs === 'number' ? opts.waitMs : 800; // wait after load before print
  let root = null;
  if (typeof rootOrSelector === 'string') {
    root = document.querySelector(rootOrSelector);
  } else {
    root = rootOrSelector;
  }
  if (!root) throw new Error('No root node for export');

  // Clone the node so that original remains unaffected
  const clone = root.cloneNode(true);

  // Inline images in the clone by creating a temporary container and manipulating nodes
  const tmp = document.createElement('div');
  tmp.style.position = 'fixed';
  tmp.style.left = '-99999px';
  tmp.style.top = '0';
  document.body.appendChild(tmp);
  tmp.appendChild(clone);

  // Inline images
  await inlineAllImages(tmp);

  // Collect CSS
  const cssText = collectStylesheetText();

  // Build HTML
  const html = `
    <!doctype html>
    <html>
    <head>
      <meta charset="utf-8">
      <meta name="viewport" content="width=device-width,initial-scale=1">
      <title>${fileName}</title>
      <style>${cssText}</style>
    </head>
    <body>
      ${clone.innerHTML}
    </body>
    </html>
  `;

  // open new window
  const w = window.open('', '_blank', 'noopener');
  if (!w) {
    document.body.removeChild(tmp);
    throw new Error('Popup blocked — allow popups for this site to export PDF');
  }

  w.document.open();
  w.document.write(html);
  w.document.close();

  // wait until load and fonts/images settle
  await new Promise((resolve) => {
    w.addEventListener('load', () => setTimeout(resolve, waitMs));
    // also fallback timeout
    setTimeout(resolve, opts.timeoutMs || 10000);
  });

  // Focus and print (user will get Print dialog; choose Save as PDF)
  w.focus();
  w.print();

  // Optionally close after some time (some browsers block closing after print)
  setTimeout(() => {
    try { w.close(); } catch (e) {}
  }, 2000);

  // cleanup
  try { document.body.removeChild(tmp); } catch (e) {}
}
